import numpy as np
import matplotlib.pyplot as plt
import scanpy as sc
from tqdm import tqdm
import os
import json

config_path = "pipeline_config.json"
sample_id = "mouse_brain_demo"
if os.path.exists(config_path):
    with open(config_path, "r", encoding="utf-8") as f:
        cfg = json.load(f)
    sample_id = cfg.get("SAMPLE_ID", "mouse_brain_demo")

# Dynamically target files generated by StarDist and preprocess
path = f"./stardist_npy/{sample_id}_labels.npy"
h5ad_in = f"{sample_id}_all.h5ad"

nuclei_mask = np.load(path, allow_pickle=True)
adata = sc.read_h5ad(h5ad_in)

nuclei_mask = np.load(path, allow_pickle=True)   # int32, (5492, 6000)
print("nuclei_mask shape:", nuclei_mask.shape, "dtype:", nuclei_mask.dtype)

H, W = nuclei_mask.shape

# Pixel coordinate scaling factor
scale = 1
diameter = 7
radius = diameter // 2

# Pre-allocate seed array, default -1 indicates "no clear nucleus matched"
seeds = np.full(adata.n_obs, -1, dtype=np.int32)

px_all = adata.obs['px'].to_numpy()
py_all = adata.obs['py'].to_numpy()

print(f"nuclei_mask shape (H,W): {H}, {W}")
print(f"Theoretical patch size per bin (center area): {(2*radius+1)} × {(2*radius+1)} = {(2*radius+1)**2} pixels")

# 2. Iterate through each bin
for i in tqdm(range(adata.n_obs), desc="Assigning seeds"):
    # (1) Scale and round coordinates
    x_pix = int(round(px_all[i] * scale))
    y_pix = int(round(py_all[i] * scale))

    # (2) Boundary check to prevent out-of-bounds
    x0 = max(0, x_pix - radius)
    x1 = min(W, x_pix + radius + 1)
    y0 = max(0, y_pix - radius)
    y1 = min(H, y_pix + radius + 1)

    patch = nuclei_mask[y0:y1, x0:x1]

    # Actual patch pixel count (edges will be smaller than 7x7)
    n_pix = patch.size
    if n_pix == 0:
        continue

    # (3) Calculate label frequencies (recommended to discard 0 as background)
    vals = patch.ravel()
    vals = vals[vals > 0]       # Remove background 0; you can remove this line if you want to consider the background
    if vals.size == 0:
        continue

    labels, counts = np.unique(vals, return_counts=True)
    best_label = labels[np.argmax(counts)]
    best_count = counts.max()

    # (4) If occurrence count exceeds half of the pixels, assign the nucleus to this bin
    if best_count > n_pix * 0.5:
        seeds[i] = best_label

# 3. Write to adata.obs['seed']
adata.obs['seed'] = seeds

# Quick statistics
n_assigned = np.sum(seeds != -1)
print(f"Total bins: {adata.n_obs}")
print(f"Number of bins assigned to a nucleus label as seed: {n_assigned}")
print(f"Percentage: {n_assigned / adata.n_obs * 100:.2f}%")

print(adata.obs['seed'])

adata.write(f"{sample_id}_seed.h5ad")
